#include "files.hpp"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>

#ifdef _WIN32
#include <fcntl.h>
#include <io.h>
#endif

std::string blitz::tools::read_file(std::filesystem::path const& file)
{
	std::ifstream stream(file, std::ios_base::binary);
	if (!stream.good()) {
		throw std::runtime_error("Reading '" + file.generic_string() + "' failed.");
	}
	return std::string(std::istreambuf_iterator<char>(stream), std::istreambuf_iterator<char>());
}

std::string blitz::tools::read_stdin()
{
#ifdef _WIN32
	_setmode(_fileno(stdin), _O_BINARY);
#endif
	return std::string(std::istreambuf_iterator<char>(std::cin), std::istreambuf_iterator<char>());
}

void blitz::tools::write_file(std::filesystem::path const& file, std::string const& data)
{
	std::ofstream stream(file, std::ios_base::binary | std::ios_base::trunc);
	stream.write(data.data(), (std::streamsize)data.size());
	stream.flush();
	if (!stream.good()) {
		throw std::runtime_error("Writing '" + file.generic_string() + "' failed.");
	}
}

std::vector<std::filesystem::path> blitz::tools::find_sources(std::filesystem::path const& directory)
{
	std::vector<std::filesystem::path> found;
	std::error_code                    ec;
	std::filesystem::recursive_directory_iterator it(directory, ec), end;
	if (ec) {
		throw std::runtime_error("Reading the directory '" + directory.generic_string() + "' failed: " + ec.message());
	}
	for (; it != end; it.increment(ec)) {
		if (ec) {
			throw std::runtime_error("Reading the directory '" + directory.generic_string() + "' failed: " + ec.message());
		}
		// A link is not followed to a file, which can be anywhere and would be rewritten with -i.
		if (it->is_symlink(ec) || !it->is_regular_file(ec)) {
			continue;
		}
		std::string extension = it->path().extension().string();
		for (auto& c : extension) {
			c = (c >= 'A' && c <= 'Z') ? char(c - 'A' + 'a') : c;
		}
		if ((extension == ".bb") || (extension == ".b3d") || (extension == ".bp")) {
			found.push_back(it->path());
		}
	}
	std::sort(found.begin(), found.end());
	return found;
}
